.plan-grid { font-family: system-ui, sans-serif; display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; padding: 12px; background: #0f172a; border-radius: 10px; }
.plan-card { background: #1e293b; border: 1px solid #334155; border-radius: 8px; padding: 10px 12px; color: #f8fafc; display: flex; justify-content: space-between; align-items: center; font-size: 13px; }
.plan-card strong { color: #38bdf8; }
.plan-card span { color: #94a3b8; font-size: 12px; }
@media (max-width: 500px) { .plan-grid { grid-template-columns: 1fr; } }

